  const d = el("dialog", { class: `dlg${wide ? " wide" : ""}${confirm ? " cf" : classic ? " cl" : mid ? " fs-card mid" : " fs-card"}` });
  const bodyBox = el("div", { class: small ? "dbody" : "dbody fs-body" }, body);
  const actBox = el("div", { class: small ? "dact" : "dact fs-ft row" });
