const rqPress = new Map(), rqFail = new Map();
const RQ_PRESS = { send: TX("decision.pending.send"), edit: TX("decision.pending.edit"), drop: TX("decision.pending.drop") };
const rqNtKey = n => `nt:${n.id}`;
