    if (HCB_MAIL.test(l)) { flush(); kids.push(el("div", { class: "hcb-chip" }, icon("mail"), el("span", {}, ...hcbNums(l.trim())))); }
    else if (HCB_COUNT.test(l) && l.trim().length <= 40) { flush(); kids.push(el("div", { class: "hcb-ln" }, ...hcbNums(l.trim()))); }
