  if (a.type === "tool_call" && isTodo && a.call_id) { TD.calls.add(a.call_id); return; }
  if (a.type !== "tool_result" || !(isTodo || (a.call_id && TD.calls.delete(a.call_id)))) return;
  const own = targetOfSource(a.source);
