  pkBox.style.left = `${Math.round(x)}px`;
  pkBox.style.top = `${Math.round(y)}px`;
  pkBox.style.width = `${Math.round(r.width)}px`;
  pkBox.style.height = `${Math.round(r.height)}px`;
