const hFmt = (v, unit) => (typeof v === "boolean" ? (v ? TX("system.fmt.on") : TX("system.fmt.off")) : v === "" ? TX("system.fmt.blank") : `${typeof v === "number" ? num(v) : v}${unit ? (unit.length === 1 ? unit : ` ${unit}`) : ""}`);
