// Layered layout: flow nodes sit in the column of their longest path from an input; file and support nodes join the
// column of the node they attach to. Shared by the simple map (one stage per column) and the full graph.
function hColumns() {
  const byId = new Map(HG.nodes.map(n => [n.id, n]));
  const flow = HG.nodes.filter(n => n.group === "flow");
  const col = new Map(flow.map(n => [n.id, 0]));
  for (let i = 0; i < flow.length; i++) for (const e of HG.edges) if (col.has(e.from) && col.has(e.to)) col.set(e.to, Math.max(col.get(e.to), col.get(e.from) + 1));
  const colOf = n => { let x = n; for (let i = 0; i < 6 && x.group !== "flow"; i++) x = byId.get(x.anchor) || x; return col.get(x.id) || 0; };
  const key = n => { const a = byId.get(n.anchor); return a && a.group !== "flow" ? key(a) + 0.5 : n.order || 0; };
  return { flow, col, colOf, key, ncol: Math.max(...flow.map(n => col.get(n.id))) + 1 };
}

// Full graph: one flow node per column is centered on the middle line, files and support nodes above and below it.
function hLayout(avail) {
  const nodes = HG.nodes;
  const { flow, col, colOf, key, ncol } = hColumns();
  const cols = Array.from({ length: ncol }, () => ({ flow: [], att: [] }));
  for (const n of flow) cols[col.get(n.id)].flow.push(n);
  for (const n of nodes) if (n.group !== "flow") cols[colOf(n)].att.push(n);
  const GX = 56, HF = hFeat && !H_MQ.matches && FC ? 90 : 72, HA = hFeat && !H_MQ.matches && FC ? 78 : 60, VG = 10, HEAD = 26;
  const CW = Math.max(150, Math.min(200, Math.floor((avail - GX * (ncol - 1)) / ncol)));
  for (const c of cols) {
    c.att.sort((a, b) => key(a) - key(b));
    const up = c.flow.length === 1 ? Math.ceil(c.att.length / 2) : 0;
    c.above = c.att.slice(0, up); c.below = c.att.slice(up);
    c.aboveH = c.above.length * (HA + VG);
    c.blockH = c.flow.length * HF + (c.flow.length - 1) * VG;
  }
  const mid = Math.max(...cols.map(c => c.aboveH + c.blockH / 2));
  const rects = {};
  let bottom = 0;
  cols.forEach((c, i) => {
    let y = HEAD + mid - c.blockH / 2 - c.aboveH;
    const x = i * (CW + GX);
    for (const [list, h] of [[c.above, HA], [c.flow, HF], [c.below, HA]]) for (const n of list) { rects[n.id] = { x, y, w: CW, h, col: i }; y += h + VG; }
    bottom = Math.max(bottom, y - VG);
  });
  return { rects, cols, width: ncol * CW + (ncol - 1) * GX, height: bottom + 8, CW, GX };
}

// Edge paths: curves between columns (right side -> left side). Inside one column the helpers feed their flow node over
// a shared bus in the gutter (one line, one arrowhead); two stacked helpers are joined by a short straight arrow.
// Several curves on one side of a card are spread a few px apart so their arrowheads stay readable.
function hRoutes(L) {
  const rows = HG.edges.filter(e => L.rects[e.from] && L.rects[e.to]).map(e => {
    const a = L.rects[e.from], b = L.rects[e.to], same = a.col === b.col;
    return { e, a, b, same, sa: same || a.col < b.col ? "r" : "l", sb: same ? "r" : a.col < b.col ? "l" : "r" };
  });
  const ports = new Map();
  const add = (id, side, r, other, k) => { const key = id + side; if (!ports.has(key)) ports.set(key, []); ports.get(key).push({ r, k, y: other.y + other.h / 2 }); };
  for (const r of rows) if (!r.same) { add(r.e.from, r.sa, r, r.b, "oa"); add(r.e.to, r.sb, r, r.a, "ob"); }
  for (const list of ports.values()) { list.sort((p, q) => p.y - q.y); list.forEach((p, i) => { p.r[p.k] = Math.max(-26, Math.min(26, (i - (list.length - 1) / 2) * 8)); }); }
  for (const r of rows) {
    const y1 = r.a.y + r.a.h / 2 + (r.oa || 0), y2 = r.b.y + r.b.h / 2 + (r.ob || 0);
    if (r.same) {
      const gap = r.b.y > r.a.y ? r.b.y - (r.a.y + r.a.h) : r.a.y - (r.b.y + r.b.h);
      const cx = r.a.x + r.a.w / 2;
      if (hNode(r.e.to).group !== "flow" && gap <= 14) {
        const down = r.b.y > r.a.y;
        r.d = `M${cx} ${down ? r.a.y + r.a.h : r.a.y}V${down ? r.b.y : r.b.y + r.b.h}`; r.lx = cx; r.ly = (r.a.y + r.b.y + r.b.h) / 2;
      } else {
        const x1 = r.a.x + r.a.w, gx = x1 + 10;
        r.d = `M${x1} ${y1}H${gx}V${y2}H${x1}`; r.lx = gx; r.ly = (y1 + y2) / 2;
      }
    } else {
      const x1 = r.sa === "r" ? r.a.x + r.a.w : r.a.x, x2 = r.sb === "l" ? r.b.x : r.b.x + r.b.w;
      const dx = Math.max(24, Math.abs(x2 - x1) * 0.5) * (x2 > x1 ? 1 : -1);
      r.d = `M${x1} ${y1}C${x1 + dx} ${y1} ${x2 - dx} ${y2} ${x2} ${y2}`; r.lx = (x1 + x2) / 2; r.ly = (y1 + y2) / 2;
    }
  }
  return rows;
}

function hCard(n, mobile) {
  const sup = n.group === "support";
  const links = mobile && n.group !== "flow" ? HG.edges.filter(e => e.from === n.id).map(e => `${hNode(e.to).label}: ${e.label}`) : [];
  const b = el("button", { type: "button", class: `hm-n${sup ? " sup" : ""}${n.group === "files" ? " fl" : ""}${mobile ? " m" : ""}${hSel === n.id ? " on" : ""}${hMine(n.id).any && hOrigin() ? " mine" : ""}`, "data-id": n.id, "aria-label": `${n.label}: ${n.summary}` },
    el("span", { class: "t" }, el("span", { class: `dot ${H_TONE[n.status] || ""}` }), n.group === "files" ? icon("file") : null, el("span", { class: "l", text: n.label }), hMark(n.id)),
    el("span", { class: "s", text: n.summary }),
    fcBadges(n.id),
    links.length ? el("span", { class: "lk", text: `→ ${links.join(" · ")}` }) : null);
  b.addEventListener("click", () => openHSheet(n.id));
  b.addEventListener("mouseenter", () => hHot(n.id));
  b.addEventListener("mouseleave", () => hHot(hSel));
  b.addEventListener("focus", () => hHot(n.id));
  b.addEventListener("blur", () => hHot(hSel));
  hNodeEls.set(n.id, b);
  return b;
}

function hHot(id) {
  if (hOv) { hOverlay(id); return; }
  for (const r of hEdgeRefs) {
    const on = !!id && (r.e.from === id || r.e.to === id);
    r.path.classList.toggle("hot", on); r.label.classList.toggle("hot", on);
    r.path.setAttribute("marker-end", on ? "url(#hm-ah-hot)" : "url(#hm-ah)");
  }
}

function hUse() {
  const p = hPj();
  if (hProjId && HGB && !p) { hProjId = ""; if (current === "harness") routeReplace("harness"); }
  HG = p ? { ...HGB, origin_view: false, nodes: p.map.nodes, edges: p.map.edges } : HGB;
  if (hSel && !hNode(hSel)) { closeHSheet(); hSel = ""; }
}

function renderHarness() {
  const box = $("#harness");
  hUse();
  hNodeEls = new Map(); hEdgeRefs = []; hGeo = new Map(); hOv = null;
  if (!HG) { clear(box).append(emptyNode(TX("common.loading"))); return; }
  const mobile = H_MQ.matches, pj = hPj();
  const onlySeg = hOrigin() ? el("div", { class: "seg", role: "group", "aria-label": TX("system.view.scope") }, ...[[false, TX("system.view.all"), TX("system.view.all_tip")], [true, TX("system.view.custom", { n: hCustomCount() }), TX("system.view.custom_tip")]].map(([v, t, tip]) => {
    const b = el("button", { type: "button", class: hOnly === v ? "on" : "", "aria-pressed": String(hOnly === v), title: tip, text: t });
    b.addEventListener("click", () => { hOnly = v; lsSet("dotz-honly", v ? "1" : "0"); renderHarness(); });
    return b;
  })) : null;
  const bar = el("div", { class: "hm-bar" },
    pj ? hProjHead(pj) : null,
    el("div", { class: "sup", text: pj ? TX("system.note.project") : hDetail ? TX("system.note.dotted") : TX("system.note.flow") }),
    onlySeg,
    el("button", { class: "btn tonal sm", type: "button", "aria-pressed": String(hDetail), title: TX("system.detail.tip"), onclick: () => { hDetail = !hDetail; try { localStorage.setItem("dotz-hdetail", hDetail ? "1" : "0"); } catch {} renderHarness(); } }, TX("system.detail.btn")),
    FC && !pj ? el("button", { class: "btn tonal sm", type: "button", "aria-pressed": String(hFeat), title: TX("system.feat.tip"), onclick: () => { hFeat = !hFeat; try { localStorage.setItem("dotz-hfeat", hFeat ? "1" : "0"); } catch {} renderHarness(); } }, TX("system.feat.btn")) : null,
    el("button", { class: "btn tonal sm", type: "button", "data-hm-refresh": "", title: TX("system.refresh"), "aria-label": TX("system.refresh"), onclick: ev => busy(ev.currentTarget, async () => { await loadHarness(); }) }, icon("refresh")),
    hOrigin() ? el("div", { class: "sup hm-legend" }, el("span", { class: "bd m", text: TX("system.mark.badge") }), TX("system.legend", { path: shortPath(hData()) })) : null);
  const parts = [bar];
  const keep = box.querySelector(".hm-scroll");
  const left = keep ? keep.scrollLeft : 0;
  parts.push(hOnlyOn() ? hCustomView() : !hDetail ? hSimple() : mobile ? hFlowList() : hCanvas($("#views").clientWidth - 48));
  if (!hMapBox || hMapBox.parentNode !== box) { clear(box); hMapBox = el("div"); hProjBox = el("div", { class: "pj" }); hFcBox = el("div", { class: "fc" }); box.append(hMapBox, hProjBox, hFcBox); fcSig = ""; }
  clear(hMapBox).append(...parts);
  clear(hProjBox).hidden = !!pj;
  if (!pj) hProjBox.append(...hProjBand());
  const sc = box.querySelector(".hm-scroll");
  if (sc) sc.scrollLeft = left;
  hHot(hSel);
  if (pj) { clear(hFcBox); fcSig = ""; } else renderFeatures();
}

/* ---------- 구성: 프로젝트 (작업 채널·홈 채널에 묶인 레인마다 한 장; data: /api/harness 의 projects) ---------- */
const hPj = () => (HGB && hProjId && (HGB.projects || []).find(p => p.id === hProjId)) || null;
const hProjWhere = (p, full) => `${(p.channels[0] || {}).name || p.name} · ${full ? p.cwd : shortPath(p.cwd)}`;
const pjSize = b => (b < 1024 ? `${b}B` : `${(b / 1024).toFixed(1)}KB`);
const pjChain = c => (c.length ? c.map(e => [e.key_file ? TX("system.pj.keyed", { name: modelName(fbBase(e.model)) }) : modelName(fbBase(e.model)), e.when ? FB_WHEN[e.when] : "", e.cap ? fbCapText(e.cap) : "", e.revert ? TX("system.pj.revert") : ""].filter(Boolean).join(" · ")).join(" → ") : TX("system.pj.none"));
const PJ_ROWS = [[TX("system.pj.model"), "model", modelName], [TX("system.pj.effort"), "effort", thinkKo], [TX("system.pj.worker_model"), "worker_model", modelName], [TX("system.pj.worker_effort"), "worker_effort", thinkKo], [TX("system.pj.runtime"), "runtime", v => v || "–"], [TX("system.pj.fallback"), "fallback", pjChain], [TX("system.pj.worker_fallback"), "worker_fallback", pjChain]];

// One field: the project's value against the global one. A differing value is emphasised like the 내 설정 marker (바뀜 badge,
// --mine) and shows global → project; an equal one is muted with "전역 기본".
function pjField(label, f, fmt) {
  const diff = f.source === "project";
  return el("div", { class: `pj-f${diff ? " diff" : ""}` }, el("span", { class: "k", text: label }),
    el("span", { class: "v" }, ...(diff
      ? [el("span", { class: "bd m", text: TX("system.pj.changed") }), el("s", { class: "was", title: TX("system.pj.global"), text: fmt(f.global) }), el("span", { class: "ar", text: "→" }), el("b", { text: fmt(f.value) })]
      : [el("span", { class: "dim", text: fmt(f.value) }), el("span", { class: "pj-g", text: TX("system.pj.global") })])));
}

function hProjCard(p) {
  const tone = statusTone(p.status), s = p.setup;
  const feat = [p.features.length ? TX("system.pj.feat", { n: p.features.length, names: `${p.features.slice(0, 3).map(f => f.name).join(", ")}${p.features.length > 3 ? " …" : ""}` }) : "", p.deny.length ? TX("system.pj.deny", { n: p.deny.length }) : ""].filter(Boolean).join(" · ");
  const b = el("div", { class: `pj-card${p.overrides ? " diff" : ""}`, role: "button", tabindex: "0", "aria-label": TX("system.pj.open_map", { name: p.name }) },
    el("div", { class: "pj-top" }, el("span", { class: `dot ${tone}` }), el("span", { class: "pj-nm", text: p.name }), el("span", { class: `tag ${tone}`, text: p.status_text }),
      p.overrides ? el("span", { class: "bd m", title: TX("system.pj.diff_tip"), text: TX("system.pj.diff_n", { n: p.overrides }) }) : el("span", { class: "pj-g", text: TX("system.pj.all_global") })),
    el("div", { class: "pj-chs" }, ...p.channels.map(c => el("span", { class: "pj-tg", title: `${c.kind_text}: ${c.name}` }, `#${c.name}`, el("span", { class: "kd", text: c.kind_text })))),
    pathCopy(p.cwd, "pj-cwd"),
    el("div", { class: "pj-fs" }, ...PJ_ROWS.map(([label, key, fmt]) => pjField(label, p.fields[key], fmt))),
    el("div", { class: "pj-sc" }, el("div", { class: "cl", text: TX("system.pj.files") }),
      p.files.length ? el("div", { class: "pj-chs" }, ...p.files.map(f => el("span", { class: "pj-tg", title: f.dir ? f.name : `${TX("system.pj.file_tip", { name: f.name, bytes: num(f.bytes), at: kstStamp(f.modified) })}${f.heading ? ` · ${f.heading}` : ""}` }, f.name, f.dir ? null : el("span", { class: "kd", text: pjSize(f.bytes) })))) : el("div", { class: "tx dim", text: TX("system.pj.none") })),
    el("div", { class: "pj-sc" }, el("div", { class: "cl", text: TX("system.pj.channel") }),
      s ? [el("div", { class: "tx", text: s.purpose }), el("div", { class: "tx dim", text: [s.logins.length ? TX("system.pj.logins_named", { n: s.logins.length, names: s.logins.map(l => l.name).join(", ") }) : TX("system.pj.logins", { n: 0 }), TX("system.pj.monitors", { n: s.monitors.length }), s.standing ? TX("system.pj.standing", { text: s.standing }) : ""].filter(Boolean).join(" · ") })] : el("div", { class: "tx dim", text: TX("system.pj.no_settings") })),
    el("div", { class: "pj-sc" }, el("div", { class: "cl", text: TX("system.pj.only_here") }), el("div", { class: `tx${feat ? "" : " dim"}`, text: feat || TX("system.pj.none") })));
  b.addEventListener("click", () => hOpenProject(p.id));
  b.addEventListener("keydown", ev => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); hOpenProject(p.id); } });
  return b;
}

function hProjBand() {
  const list = HGB.projects || [];
  const head = el("div", { class: "pj-hd" }, el("span", { class: "t", text: TX("system.pj.head", { n: list.length }) }),
    el("span", { class: "sup", text: list.length ? TX("system.pj.sup_some") : TX("system.pj.sup_none") }),
    list.length ? el("span", { class: "pj-lg" }, el("span", { class: "bd m", text: TX("system.pj.changed") }), TX("system.pj.lg_diff"), el("span", { class: "pj-g", text: TX("system.pj.global") }), TX("system.pj.lg_same")) : null);
  return list.length ? [head, el("div", { class: "pj-row" }, ...list.map(hProjCard))] : [head];
}

function hProjHead(p) {
  const back = el("button", { class: "btn tonal sm", type: "button", onclick: () => hOpenProject("") }, icon("back"), TX("system.pj.back"));
  return el("div", { class: "pj-bk" }, back,
    el("span", { class: "pj-title" }, el("span", { class: `dot ${statusTone(p.status)}` }), p.name, ...p.channels.filter(c => c.kind !== "thread").map(c => el("span", { class: "pj-tg" }, `#${c.name}`, el("span", { class: "kd", text: c.kind_text })))),
    hScopeTag("project", hProjWhere(p), false, hProjWhere(p, true)));
}

// Opens a project's own map (or the main map with ""); the hash `#harness/project/<id>` restores it on reload.
async function hOpenProject(id) {
  if (hDirty && hDirty() && !await ask(TX("system.pj.dirty.title"), TX("system.pj.dirty.body"), TX("system.pj.dirty.ok"), true)) return;
  closeHSheet(); hSel = "";
  hProjId = id;
  routeReplace(id ? `harness/project/${enc(id)}` : "harness");
  renderHarness();
  $("#views").scrollTop = 0;
}

// Free-text request about one card of the project map; always carries the 범위: 프로젝트 line.
function hProjAsk(p, n, drafts) {
  const where = hProjWhere(p, true);
  const ta = el("textarea", { class: "fi hs-ta", rows: 3, spellcheck: "false", placeholder: TX("system.pj.ask.ph"), "aria-label": TX("system.pj.ask.aria") });
  const send = el("button", { class: "btn tonal sm", type: "button", disabled: true }, TX("system.pj.ask.send", { bot: botName }));
  const note = el("div", { class: "note" });
  ta.addEventListener("input", () => { send.disabled = !ta.value.trim(); });
  send.onclick = async () => {
    send.disabled = true;
    try { const at = await hRequest(`${n.label}: ${ta.value.trim()}`, hScope("project", where)); note.className = "note ok"; note.textContent = TX("system.sw.sent", { at }); ta.value = ""; hFlash(send, TX("system.pj.ask.done")); }
    catch (e) { note.className = "note err"; note.textContent = e.message; toast(e.message, true); send.disabled = false; }
  };
  drafts.push(() => ta.value.trim() !== "");
  return el("div", { class: "hs-set" }, ta, el("div", { class: "btns hs-act" }, hScopeTag("project", hProjWhere(p), false, where), send), note);
}

function hCanvas(avail) {
  const L = hLayout(avail || 1000);
  const canvas = el("div", { class: "hm-canvas", style: `width:${L.width}px;height:${L.height}px` });
  const svg = hSvg("svg", { class: "hm-svg", width: L.width, height: L.height, viewBox: `0 0 ${L.width} ${L.height}` });
  const defs = hSvg("defs");
  for (const [id, cls] of [["hm-ah", "hm-ah"], ["hm-ah-hot", "hm-ah hot"]]) {
    const m = hSvg("marker", { id, viewBox: "0 0 8 8", refX: "7", refY: "4", markerWidth: "7", markerHeight: "7", orient: "auto" });
    m.append(hSvg("path", { d: "M0 0L8 4L0 8z", class: cls })); defs.append(m);
  }
  svg.append(defs);
  const labels = hSvg("g");
  for (const r of hRoutes(L)) {
    const sup = hNode(r.e.from).group !== "flow" || hNode(r.e.to).group !== "flow";
    const path = hSvg("path", { d: r.d, class: `hm-edge${sup ? " sup" : ""}`, "marker-end": "url(#hm-ah)" });
    const tip = hSvg("title");
    tip.textContent = `${hNode(r.e.from).label} → ${hNode(r.e.to).label}: ${r.e.label}`;
    path.append(tip);
    const label = hSvg("text", { x: r.lx, y: r.ly + 3.5, class: "hm-lb", "text-anchor": "middle" });
    label.textContent = r.e.label;
    svg.append(path); labels.append(label);
    hEdgeRefs.push({ e: r.e, path, label });
  }
  svg.append(labels);
  canvas.append(svg);
  L.cols.forEach((c, i) => canvas.append(el("div", { class: "hm-ch", style: `left:${i * (L.CW + L.GX)}px;width:${L.CW}px`, text: H_COLS[i] || "" })));
  for (const n of HG.nodes) { const r = L.rects[n.id]; const b = hCard(n, false); b.style.cssText = `left:${r.x}px;top:${r.y}px;width:${r.w}px;height:${r.h}px`; canvas.append(b); }
  return el("div", { class: "hm-scroll" }, canvas);
}

// Phone: the same nodes as a vertical flow, one step per column, with the edge labels as the arrows between steps.
function hFlowList() {
  const L = hLayout(1000);
  const wrap = el("div", { class: "hm-flow" });
  L.cols.forEach((c, i) => {
    wrap.append(el("div", { class: "sec", text: H_COLS[i] || "" }));
    const stack = el("div", { class: "hm-stack" });
    for (const n of [...c.flow, ...c.att]) stack.append(hCard(n, true));
    wrap.append(stack);
    const next = L.cols[i + 1];
    if (next) {
      const from = new Set(c.flow.map(n => n.id)), to = new Set(next.flow.map(n => n.id));
      const labels = [...new Set(HG.edges.filter(e => from.has(e.from) && to.has(e.to)).map(e => e.label))];
      wrap.append(el("div", { class: "hm-down" }, icon("down"), el("span", { text: labels.slice(0, 3).join(" · ") })));
    }
  });
  return wrap;
}

// Simple map: the main line only. One card per stage (the inputs share one card of rows); the prompt files and support
// systems of a stage are chips on its card. A support node's edges are not drawn until a chip or card is hovered/focused.
const H_MANY = TX("system.many_in");
const hShort = n => n.label.replace(/\s*\(.*\)$/, "");
const hSick = n => n.status === "warn" || n.status === "err";

function hStages() {
  const { flow, col, colOf, key, ncol } = hColumns();
  const st = Array.from({ length: ncol }, (_, i) => ({ label: H_COLS[i] || "", main: [], chips: [] }));
  for (const n of flow) st[col.get(n.id)].main.push(n);
  for (const n of HG.nodes) if (n.group !== "flow") st[colOf(n)].chips.push(n);
  for (const s of st) s.chips.sort((a, b) => key(a) - key(b));
  return st;
}

function hStageLabel(a, b) {
  const from = new Set(a.main.map(n => n.id)), to = new Set(b.main.map(n => n.id));
  const labels = [...new Set(HG.edges.filter(e => from.has(e.from) && to.has(e.to)).map(e => e.label))];
  return labels.length > 1 ? H_MANY : labels[0] || "";
}

function hChip(n) {
  const b = el("button", { type: "button", class: `hm-chip${hSick(n) ? ` ${n.status}` : n.status === "off" ? " off" : ""}${hOrigin() && hMine(n.id).any ? " mine" : ""}`, "data-id": n.id, title: `${n.label}: ${n.summary}`, "aria-label": `${n.label}: ${n.summary}` },
    el("span", { class: `dot ${H_TONE[n.status] || ""}` }), el("span", { class: "l", text: hShort(n) }), hMark(n.id), fcBadges(n.id, true));
  hNodeEls.set(n.id, b); hGeo.set(n.id, b);
  return b;
}

// Stage card frame shared by 전체 and 커스텀: the connector from the previous stage (a chevron in the gap, drawn by CSS for the
// breakpoint) and a "<previous stage>에서 · <edge label>" line, then a header with the step number, title and a count chip.
function hFrom(stages, i) {
  if (!i) return [el("div", { class: "hm-from", text: TX("system.from.start") })];
  const p = stages[i - 1], lb = hStageLabel(p, stages[i]), from = p.main.length === 1 ? hShort(p.main[0]) : p.label;
  return [el("span", { class: "hm-ar", "aria-hidden": "true" }, icon("chev")), el("div", { class: "hm-from", title: `${TX("system.from.stage", { from })}${lb ? ` · ${lb}` : ""}` }, TX("system.from.stage", { from }), lb ? el("b", { text: lb }) : null)];
}
const hNo = i => el("span", { class: "hm-no", "aria-hidden": "true", text: String(i + 1) });
const hCount = (n, title) => (n ? el("span", { class: "tag hm-ct", title, text: TX("system.count.items", { n }) }) : null);
// A source path as people read it (like custom.js shortPath): the last two names, the full path in the title.
const hPath = p => { const parts = String(p).split("/").filter(Boolean); return parts.length > 2 ? `…/${parts.slice(-2).join("/")}` : String(p); };

function hStageCard(s, i, stages) {
  const one = s.main.length === 1 ? s.main[0] : null;
  const bad = (one ? s.chips : s.main).filter(hSick);
  const ids = [...s.main, ...s.chips].map(n => n.id);
  const kids = [
    el("span", { class: "t" },
      hNo(i),
      one ? el("span", { class: `dot ${H_TONE[one.status] || ""}` }) : null,
      el("span", { class: "l", text: one ? one.label : s.label }),
      one ? null : hCount(s.main.length + s.chips.length, TX("system.count.items_tip")),   // a one-item stage says its extras below (함께 실행되는 항목 · N)
      one && one.status !== "ok" ? el("span", { class: `tag ${H_TONE[one.status] || ""}`, text: H_STATE[one.status] || "" }) : null,
      bad.length ? el("span", { class: `tag ${bad.some(n => n.status === "err") ? "err" : "warn"}`, title: bad.map(n => n.label).join(", "), text: TX("system.count.warn", { n: bad.length }) }) : null),
    one ? el("span", { class: "s", text: one.summary }) : null,
    fcBadges(ids), hMark(ids, true)];
  const head = one ? el("button", { type: "button", class: "hm-sh", "aria-label": `${one.label}: ${one.summary}` }, ...kids) : el("div", { class: "hm-sh" }, ...kids);
  const card = el("div", { class: `hm-st${one ? " one" : ""}${hOrigin() && hMine(ids).any ? " mine" : ""}`, "data-id": one ? one.id : null }, ...hFrom(stages, i), head);
  const list = el("div", { class: "hm-list" });
  if (one) { hNodeEls.set(one.id, card); hGeo.set(one.id, head); }
  else list.append(el("div", { class: "hm-rows" }, ...s.main.map(n => {
    const r = el("button", { type: "button", class: "hm-row", "data-id": n.id, title: `${n.label}: ${n.summary}`, "aria-label": `${n.label}: ${n.summary}` },
      el("span", { class: `dot ${H_TONE[n.status] || ""}` }), el("span", { class: "tx" }, el("span", { class: "l", text: n.label }), el("span", { class: "s", text: n.summary })), hMark(n.id));
    hNodeEls.set(n.id, r); hGeo.set(n.id, r);
    return r;
  })));
  if (s.chips.length) list.append(el("div", { class: "hm-with" }, el("div", { class: "wl", text: TX("system.with.head", { n: s.chips.length }) }), el("div", { class: "hm-chips" }, ...s.chips.map(hChip))));
  if (list.firstChild) card.append(list);
  return card;
}

function hSimple() {
  const stages = hStages(), wrap = el("div", { class: "hm-simple" });
  stages.forEach((s, i) => wrap.append(hStageCard(s, i, stages)));
  const svg = hSvg("svg", { class: "hm-ov", "aria-hidden": "true" });
  const m = hSvg("marker", { id: "hm-ov-ah", viewBox: "0 0 8 8", refX: "7", refY: "4", markerWidth: "7", markerHeight: "7", orient: "auto" });
  m.append(hSvg("path", { d: "M0 0L8 4L0 8z", class: "hm-ah hot" }));
  svg.append(hSvg("defs")); svg.firstChild.append(m);
  hOv = svg; wrap.append(svg);
  const idOf = ev => { const t = ev.target.closest("[data-id]"); return t ? t.dataset.id : ""; };
  wrap.addEventListener("click", ev => { const id = idOf(ev); if (id) openHSheet(id); });
  wrap.addEventListener("mouseover", ev => hHot(idOf(ev) || hSel));
  wrap.addEventListener("mouseleave", () => hHot(hSel));
  wrap.addEventListener("focusin", ev => { const id = idOf(ev); if (id) hHot(id); });
  wrap.addEventListener("focusout", () => hHot(hSel));
  return wrap;
}

