  CM.drafting.add(c.id); cmPaintChat(false);
  setTimeout(() => { if (CM.drafting.delete(c.id)) { cmPaintChat(false); toast(TX("mon.cm.draft_late"), true); } }, 120000);
  try { await cmApi(`/api/comments/comment/${enc(c.id)}/draft`, "POST", {}); }
