  const top = convSide.querySelector('.cv-row[data-t="worklog"]'), card = top && top.closest(".cv-card");
  if (!card) return null;
  const unit = el("div", { class: "cv-grp" }, el("div", { class: "cv-sec", role: "presentation", text: TX("home.sys.running") }), el("div", { class: "cv-card" }));
  card.after(unit);
