  if (!c.snap) return [el("div", { class: "card empty rv-none" }, el("div", { text: TX("relay.none_title", { name: who }) }), el("div", { class: "sup", text: TX("relay.none_hint") })), rvFoot(t, null)];
  const s = c.snap;
